// Define a struct to hold the broadcast‐grid information
#[derive(Debug, Clone)]
pub struct BroadcastObject {
    // shape.0 = length of x, shape.1 = length of y
    shape: (usize, usize),
    x: Vec<f32>,
    y: Vec<f32>,
}

impl BroadcastObject {
    /// Returns the shape of the broadcast grid as (len_x, len_y).
    pub fn shape(&self) -> (usize, usize) {
        self.shape
    }

    /// Returns Some((x[i], y[j])) if (i, j) is in‐bounds, else None.
    pub fn get(&self, i: usize, j: usize) -> Option<(f32, f32)> {
        if i < self.shape.0 && j < self.shape.1 {
            Some((self.x[i], self.y[j]))
        } else {
            None
        }
    }
}

/// Constructs a BroadcastObject representing the Cartesian product of `x` and `y`.
pub fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject {
    // Both x and y are non‐empty by assumption, but even if empty this still works.
    let shape = (x.len(), y.len());
    BroadcastObject { shape, x, y }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_broadcast_basic() {
        let a = vec![1.0_f32, 2.0, 3.0];
        let b = vec![10.0_f32, 20.0];
        let bc = broadcast(a, b);
        assert_eq!(bc.shape(), (3, 2));

        // Check all valid pairs
        for i in 0..3 {
            for j in 0..2 {
                let (xi, yj) = bc.get(i, j).unwrap();
                assert_eq!(xi, (i + 1) as f32);
                assert_eq!(yj, (j + 1) as f32 * 10.0);
            }
        }

        // Out‐of‐bounds
        assert!(bc.get(3, 0).is_none());
        assert!(bc.get(0, 2).is_none());
        assert!(bc.get(3, 2).is_none());
    }
}